'use strict';
var state={input:null,draft:null,plan:null,automatic:null,files:[],fileAnalysis:null,fileMetadata:[],fileAnalysisKey:'',activeStep:0,resultTab:'tasks',largeStage:'modules',largeBoardTab:'modules',chatBaseline:null,chatHistory:[],chatDelta:'',lastSavedFilename:null};
var ivChat={started:false,messages:[]};
function el(id){return document.getElementById(id)}
function esc(value){var d=document.createElement('div');d.textContent=value==null?'':String(value);return d.innerHTML}
function splitTags(value){return String(value||'').split(/[,，]/).map(function(x){return x.trim()}).filter(Boolean)}
function projectDays(){var s=el('startDate').value,e=el('endDate').value;if(!e)return 1;if(!s)return 14;return Math.max(1,Math.ceil((new Date(e)-new Date(s))/86400000)+1)}
function showNotice(message,type){var n=el('notice');n.textContent=message;n.className='notice '+(type||'info');setTimeout(function(){n.classList.add('hidden')},3500)}
function renderMd(text){if(!text)return '';var lines=String(text).split(/\r?\n/);var html=[],inTable=false,tableRows=[],listType=null,listItems=[];function inline(s){s=esc(s);s=s.replace(/\*\*(.+?)\*\*/g,'<strong>$1</strong>');s=s.replace(/(?<!\w)\*(.+?)\*(?!\w)/g,'<em>$1</em>');s=s.replace(/`([^`]+)`/g,'<code>$1</code>');return s}function flushTable(){if(!inTable)return;if(tableRows.length){var th=tableRows[0].map(function(c){return '<th>'+inline(c)+'</th>'}).join('');var trs=tableRows.slice(1).map(function(r){return '<tr>'+r.map(function(c){return '<td>'+inline(c)+'</td>'}).join('')+'</tr>'}).join('');html.push('<table class="md-table"><thead><tr>'+th+'</tr></thead><tbody>'+trs+'</tbody></table>')}inTable=false;tableRows=[]}function flushList(){if(!listType)return;html.push('<'+listType+'>'+listItems.join('')+'</'+listType+'>');listType=null;listItems=[]}lines.forEach(function(line){var trimmed=line.trim();if(trimmed.indexOf('|')>=0&&trimmed.split('|').length>=3){flushList();inTable=true;var cells=trimmed.replace(/^\||\|$/g,'').split('|').map(function(c){return c.trim()});if(cells.length===1&&/^[-:\s]+$/.test(cells[0]))return;tableRows.push(cells);return}flushTable();if(!trimmed){flushList();html.push('<p></p>');return}var h=/^(#{1,4})\s+(.*)$/.exec(trimmed);if(h){flushList();html.push('<h'+h[1].length+'>'+inline(h[2])+'</h'+h[1].length+'>');return}if(/^[-*]\s+/.test(trimmed)){if(listType!=='ul'){flushList();listType='ul';listItems=[]}listItems.push('<li>'+inline(trimmed.replace(/^[-*]\s+/,''))+'</li>');return}if(/^\d+\.\s+/.test(trimmed)){if(listType!=='ol'){flushList();listType='ol';listItems=[]}listItems.push('<li>'+inline(trimmed.replace(/^\d+\.\s+/,''))+'</li>');return}flushList();html.push('<p>'+inline(trimmed)+'</p>')});flushTable();flushList();return html.join('')}
async function jsonRequest(url,body){var response=await fetch(url,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});var data=await response.json();if(!response.ok)throw Error(typeof data.detail==='string'?data.detail:JSON.stringify(data.detail||data));return data}
function projectMode(){var checked=document.querySelector('input[name="projectMode"]:checked');return checked?checked.value:'small_group'}
function isLargeProject(){if(state.input&&state.input.project_mode)return state.input.project_mode==='large_project';return projectMode()==='large_project'}
﻿﻿function renderSteps(){var steps=isLargeProject()?['项目配置','大模块拆解','骨干认领','子任务拆解','分工招募','最终方案']:['项目配置','任务拆解','智能分工','最终方案'];el('stepNav').innerHTML=steps.map(function(name,index){var enabled;if(isLargeProject()){enabled=index===0||(index<=3&&state.draft)||(index>=4&&state.plan)}else{enabled=index===0||(index===1&&state.draft)||(index>=2&&state.plan)}var cls=index===state.activeStep?'active':(index<state.activeStep?'done':'');return '<button '+(enabled?'':'disabled')+' data-step="'+index+'" class="'+cls+'"><span>'+(index+1)+'</span>'+esc(name)+'</button>'}).join('');el('stepNav').querySelectorAll('[data-step]').forEach(function(button){button.onclick=function(){navigateToStep(+button.dataset.step)}})}
function navigateToStep(step){if(isLargeProject()){if(step===0)setView('config',0);else if(step===1&&state.draft){state.largeStage='modules';renderDraftView();setView('draft',1)}else if(step===2&&state.draft){state.largeStage='backbones';renderDraftView();setView('draft',2)}else if(step===3&&state.draft){state.largeStage='tasks';renderDraftView();setView('draft',3)}else if(step===4&&state.plan){renderBoard();setView('board',4)}else if(step===5&&state.plan){renderFinal();setView('final',5)}}else{if(step===0)setView('config',0);else if(step===1&&state.draft){renderDraftView();setView('draft',1)}else if(step===2&&state.plan){renderBoard();setView('board',2)}else if(step===3&&state.plan){renderFinal();setView('final',3)}}}
function setView(name,step){['config','draft','board','final'].forEach(function(v){var n=el(v+'View');if(n)n.classList.toggle('hidden',v!==name)});state.activeStep=step;renderSteps()}
function addMember(member){member=member||{};var mode=member.profile_mode||'tags';var row=document.createElement('div');row.className='member-row';row.dataset.mode=mode;var skillsHtml=mode==='tags'?'<input class="member-skills" placeholder="技能标签，逗号分隔" value="'+esc((member.skill_tags||[]).join(','))+'">':'<textarea class="member-bio" rows="2" placeholder="用自然语言描述擅长什么">'+esc(member.bio||'')+'</textarea>';var unavailStr=(member.unavailable_dates||[]).map(function(d){return typeof d==='string'?d.slice(0,10):d}).join(',');row.innerHTML='<input class="member-name" placeholder="姓名" value="'+esc(member.name||'')+'"><select class="member-mode"><option value="tags" '+(mode==='tags'?'selected':'')+'>标签</option><option value="bio" '+(mode==='bio'?'selected':'')+'>简介</option></select>'+skillsHtml+'<div class="hours-input"><input class="member-hours" type="number" min=".5" step=".5" value="'+(member.daily_available_hours||4)+'"><span>h/天</span></div><input class="member-unavailable" type="text" placeholder="不可用日期(如2026-08-05)" value="'+esc(unavailStr)+'"><button type="button" class="remove-member icon-danger">×</button>';row.querySelector('.remove-member').onclick=function(){row.remove()};var modeSel=row.querySelector('.member-mode');modeSel.onchange=function(){toggleMemberMode(row,modeSel.value)};el('members').appendChild(row)}
function toggleMemberMode(row,mode){var old=row.querySelector(mode==='tags'?'.member-bio':'.member-skills');var oldVal=old?old.value:'';if(old)old.remove();var newHtml=mode==='tags'?'<input class="member-skills" placeholder="技能标签" value="">':'<textarea class="member-bio" rows="2" placeholder="描述擅长什么">'+esc(oldVal)+'</textarea>';row.dataset.mode=mode;row.querySelector('.hours-input').insertAdjacentHTML('beforebegin',newHtml)}
function collectInput(){var days=projectDays();var members=Array.from(document.querySelectorAll('.member-row')).map(function(row){var daily=+row.querySelector('.member-hours').value||4;var unavailStr=row.querySelector('.member-unavailable')?row.querySelector('.member-unavailable').value:'';var unavailableDates=splitTags(unavailStr).filter(function(s){return/^\d{4}-\d{2}-\d{2}$/.test(s)});var mode=row.dataset.mode||'tags';var skillTags=mode==='tags'?splitTags(row.querySelector('.member-skills')?row.querySelector('.member-skills').value:''):[];var bio=mode==='bio'?(row.querySelector('.member-bio')?row.querySelector('.member-bio').value:''):'';return{name:row.querySelector('.member-name').value.trim(),skill_tags:skillTags,daily_available_hours:daily,available_hours:daily*days,unavailable_dates:unavailableDates,profile_mode:mode,bio:bio}}).filter(function(m){return m.name});return{course:{name:el('projectName').value.trim(),description:el('background').value.trim()},members:members,deadline:el('endDate').value,additional_requirements:el('requirements').value.trim(),background:el('background').value.trim(),requirements:el('requirements').value.trim(),default_start_date:el('startDate').value||null,default_end_date:el('endDate').value||null,uploaded_files:state.files.map(function(f){return{name:f.name,size:f.size}}),requirement_analysis:state.fileAnalysis||{},project_mode:projectMode()}}
function loadDemoCase(){var today=new Date(),start=new Date(today.getTime()+86400000),end=new Date(today.getTime()+15*86400000);var iso=function(d){return d.toISOString().slice(0,10)};el('projectName').value='校园低碳生活倡议发布';el('background').value='面向全校同学策划一次低碳生活倡议活动，完成调研、内容策划、视觉物料、线上传播和效果复盘，最终形成可展示的活动方案与总结报告。';el('requirements').value='两周内完成；需要一份调研摘要、一套宣传图文、一场线下倡议活动和一份复盘报告。';el('startDate').value=iso(start);el('endDate').value=iso(end);el('members').innerHTML='';addMember({name:'林悦',skill_tags:['调研','数据分析','访谈','报告撰写']});addMember({name:'陈曦',skill_tags:['文案写作','报告撰写','活动策划']});addMember({name:'周航',skill_tags:['视觉设计','PPT','摄影','文案编辑']});state.files=[];state.fileAnalysis=null;state.fileMetadata=[];state.fileAnalysisKey='';el('files').value='';el('fileList').innerHTML='';showNotice('演示案例已载入','success')}
function updateModeHint(){var hint=el('memberSectionHint'),title=el('memberSectionTitle');if(projectMode()==='large_project'){title.textContent='骨干成员（可跳过）';hint.textContent='大型项目先拆大模块，再在「骨干认领」阶段添加骨干。此处可预填，也可跳过。';hint.classList.remove('hidden')}else{title.textContent='团队成员';hint.classList.add('hidden')}}
async function analyzeFiles(){if(!state.files.length)return;var key=state.input.background+'|'+state.files.map(function(f){return[f.name,f.size,f.lastModified].join(':')}).join('|');if(state.fileAnalysis&&state.fileAnalysisKey===key){state.input.uploaded_files=state.fileMetadata;state.input.requirement_analysis=state.fileAnalysis;return}var fd=new FormData();state.files.forEach(function(f){fd.append('files',f)});fd.append('background',state.input.background);var response=await fetch('/api/analyze-files',{method:'POST',body:fd});var data=await response.json();if(!response.ok)throw Error(data.detail||'文件分析失败');state.fileAnalysis=data.analysis;state.fileMetadata=data.files;state.fileAnalysisKey=key;state.input.uploaded_files=data.files;state.input.requirement_analysis=data.analysis}
﻿﻿async function generateDraft(useAi,btn){var button=btn||el('generateBtn');var oldHtml=button.innerHTML;button.disabled=true;button.innerHTML='<span class="spinner-inline"></span>'+(useAi?'AI 生成中...':'快速生成中...');try{state.input=collectInput();if(!isLargeProject()&&!state.input.members.length)throw Error('请至少填写一名成员');if(!state.input.course.name)throw Error('请填写项目名称');if(!state.input.deadline)throw Error('请选择截止日期');if(state.files.length)await analyzeFiles();var data=await jsonRequest('/api/draft',{input:state.input,use_ai:useAi});state.draft=data.plan;if(isLargeProject())state.largeStage='modules';renderDraftView();setView('draft',1);resetChatMemory();var usedFallback=data.plan.summary.indexOf('AI 拆解本次未成功')===0;showNotice(usedFallback?'AI 本次未返回可用草案，已改用文件任务蓝图':'任务草案已生成',usedFallback?'info':'success')}catch(error){showNotice(error.message,'error')}finally{button.disabled=false;button.innerHTML=oldHtml}}
function renderDraftView(){var stageNav=el('largeStageNav');if(isLargeProject()){stageNav.classList.remove('hidden');renderLargeStageNav();if(state.largeStage==='modules')renderLargeModules();else if(state.largeStage==='backbones')renderLargeBackbones();else renderLargeTasks()}else{stageNav.classList.add('hidden');renderSmallDraft()}}
function renderLargeStageNav(){var stages=[{id:'modules',name:'大模块拆解',num:1},{id:'backbones',name:'骨干认领',num:2},{id:'tasks',name:'子任务拆解',num:3}];el('largeStageNav').innerHTML=stages.map(function(s){return '<button class="large-stage-tab '+(state.largeStage===s.id?'active':'')+'" data-stage="'+s.id+'"><span>'+s.num+'</span>'+esc(s.name)+'</button>'}).join('');el('largeStageNav').querySelectorAll('.large-stage-tab').forEach(function(btn){btn.onclick=function(){var target=btn.dataset.stage;syncCurrentStage().then(function(){state.largeStage=target;renderDraftView();var stepMap={modules:1,backbones:2,tasks:3};state.activeStep=stepMap[target];renderSteps()}).catch(function(e){showNotice(e.message,'error')})}})}
function updateDraftFooter(){var btn=el('confirmDraftBtn'),hint=el('draftHint');if(isLargeProject()){if(state.largeStage==='modules'){btn.textContent='下一步：骨干认领';hint.textContent='编辑模块后进入骨干认领'}else if(state.largeStage==='backbones'){btn.textContent='下一步：子任务拆解';hint.textContent='为每个模块认领骨干后继续'}else{btn.textContent='确认拆解并开始分工';hint.textContent=''}}else{btn.textContent='确认拆解并开始分工';hint.textContent=''}}
function renderSmallDraft(){el('draftToolbar').innerHTML='<div class="toolbar-title"><h2>任务拆解</h2><p>编辑任务后确认开始分工</p></div><div class="toolbar-actions"><button class="btn btn-ghost" id="addTaskBtn">＋ 新增任务</button><button class="btn btn-ghost" id="mergeTaskBtn">合并选中</button><button class="btn btn-ghost" id="redraftBtn">重新生成</button></div>';el('draftSummary').innerHTML='<strong>'+esc(state.draft.summary)+'</strong><p>'+esc(state.draft.reasoning||'任务已按专业能力、交付流程和依赖关系拆解。')+'</p>';var tasks=state.draft.tasks.slice().sort(function(a,b){return a.order-b.order});el('taskEditor').innerHTML=tasks.map(renderTaskCard).join('');updateDraftFooter();var total=tasks.reduce(function(s,t){return s+t.estimated_hours},0);el('draftTotal').textContent=tasks.length+' 项任务 · '+total.toFixed(1)+' 小时';el('addTaskBtn').onclick=function(){mutateDraft([{op:'add'}]).catch(function(e){showNotice(e.message,'error')})};el('mergeTaskBtn').onclick=mergeSelectedTasks;el('redraftBtn').onclick=function(){generateDraft(true,el('redraftBtn'))};bindTaskCards()}
function renderTaskCard(task){var estimateHint=task.estimate_reason?'<small class="estimate-hint" title="'+esc(task.estimate_reason)+'">参考 '+task.estimate_min_hours+'-'+task.estimate_max_hours+'h</small>':'';var memberOpts=(state.input.members||[]).map(function(m){return '<option '+(m.name===task.assignee_id?'selected':'')+'>'+esc(m.name)+'</option>'}).join('');return '<article class="task-edit-card" data-id="'+esc(task.id)+'"><div class="task-edit-top"><input type="checkbox" class="task-select"><span class="drag-handle" draggable="true" title="拖动排序">⋮⋮</span><span class="task-code">'+esc(task.id)+'</span><input class="task-name-input" value="'+esc(task.name)+'"><button class="split-task btn-small" type="button">拆分</button><button class="remove-task icon-danger" type="button">×</button></div><textarea class="task-description" rows="2">'+esc(task.description)+'</textarea><div class="task-fields"><label>预计工时<input class="task-hours-input" type="number" min=".5" step=".5" value="'+task.estimated_hours+'">'+estimateHint+'</label><label>建议人数<input class="task-people" type="number" min="1" max="10" value="'+(task.suggested_people||1)+'"></label><label>执行阶段<select class="task-stage">'+['准备','执行','收尾','自定义'].map(function(s){return '<option '+(s===task.execution_stage?'selected':'')+'>'+s+'</option>'}).join('')+'</select></label><label>自定义阶段<input class="task-custom-stage" value="'+esc(task.custom_stage||'')+'"></label><label>开始日期<input class="task-start" type="date" value="'+(task.start_date?String(task.start_date).slice(0,10):'')+'"></label><label>截止日期<input class="task-end" type="date" value="'+(task.end_date?String(task.end_date).slice(0,10):'')+'"></label><label>所需技能<input class="task-skills" value="'+esc((task.required_skills||[]).join(','))+'"></label><label>负责人<select class="task-assignee"><option value="">未分配</option>'+memberOpts+'</select></label><label>依赖任务<input class="task-dependencies" value="'+esc((task.dependencies||[]).join(','))+'"></label></div></article>'}
function taskFromCard(card){var old=state.draft.tasks.find(function(t){return t.id===card.dataset.id});if(!old)return null;return Object.assign({},old,{name:card.querySelector('.task-name-input').value.trim(),description:card.querySelector('.task-description').value.trim(),estimated_hours:+card.querySelector('.task-hours-input').value,suggested_people:+card.querySelector('.task-people').value||1,execution_stage:card.querySelector('.task-stage').value,custom_stage:card.querySelector('.task-custom-stage').value.trim()||null,start_date:card.querySelector('.task-start').value||null,end_date:card.querySelector('.task-end').value||null,required_skills:splitTags(card.querySelector('.task-skills').value),dependencies:splitTags(card.querySelector('.task-dependencies').value),assignee_id:card.querySelector('.task-assignee')?(card.querySelector('.task-assignee').value||null):old.assignee_id})}
function collectDraftTasks(){return Array.from(document.querySelectorAll('.task-edit-card')).map(taskFromCard).filter(Boolean)}
function bindTaskCards(){document.querySelectorAll('.task-edit-card').forEach(function(card){card.querySelector('.remove-task').onclick=function(){mutateDraft([{op:'remove',task_id:card.dataset.id}]).catch(function(e){showNotice(e.message,'error')})};card.querySelector('.split-task').onclick=function(){syncDraftTasks().then(function(){return mutateDraft([{op:'split',task_id:card.dataset.id}])}).catch(function(e){showNotice(e.message,'error')})};var handle=card.querySelector('.drag-handle');handle.ondragstart=function(e){card.classList.add('dragging');e.dataTransfer.effectAllowed='move';e.dataTransfer.setData('text/task-id',card.dataset.id)};handle.ondragend=function(){card.classList.remove('dragging')};card.ondragover=function(e){e.preventDefault();e.dataTransfer.dropEffect='move'};card.ondrop=function(e){e.preventDefault();var src=e.dataTransfer.getData('text/task-id');var ids=state.draft.tasks.slice().sort(function(a,b){return a.order-b.order}).map(function(t){return t.id});var from=ids.indexOf(src),to=ids.indexOf(card.dataset.id);if(from<0||to<0||from===to)return;ids.splice(to,0,ids.splice(from,1)[0]);mutateDraft([{op:'reorder',ordered_ids:ids}]).catch(function(e){showNotice(e.message,'error')})}})}
async function syncDraftTasks(){var tasks=collectDraftTasks();for(var i=0;i<tasks.length;i++){if(tasks[i].execution_stage==='自定义'&&!tasks[i].custom_stage)throw new Error('任务 '+tasks[i].id+' 选了自定��阶段，请填写名称')}var ops=tasks.map(function(t){return{op:'update',task_id:t.id,task:t}});if(ops.length)state.draft=await jsonRequest('/api/draft/mutate',{plan:state.draft,operations:ops});return state.draft}
async function mutateDraft(operations){state.draft=await jsonRequest('/api/draft/mutate',{plan:state.draft,operations:operations});renderDraftView()}
function mergeSelectedTasks(){var ids=Array.from(document.querySelectorAll('.task-select:checked')).map(function(cb){return cb.closest('.task-edit-card').dataset.id});if(ids.length<2){showNotice('请至少选中两项任务','info');return}mutateDraft([{op:'merge',task_ids:ids}]).catch(function(e){showNotice(e.message,'error')})}
﻿﻿function renderLargeModules(){el('draftToolbar').innerHTML='<div class="toolbar-title"><h2>大模块拆解</h2><p>编辑模块名称与描述，可拖拽排序、合并或新增</p></div><div class="toolbar-actions"><button class="btn btn-ghost" id="addModuleBtn">＋ 新增模块</button><button class="btn btn-ghost" id="mergeModuleBtn">合并选中模块</button><button class="btn btn-ghost" id="redraftModuleBtn">重新生成</button></div>';el('draftSummary').innerHTML='<strong>'+esc(state.draft.summary)+'</strong><p>大型项目先拆成大模块，每个模块后续由骨干认领，再拆子任务。拖动模块卡片左侧手柄可调整顺序。</p>';var modules=(state.draft.modules||[]).slice().sort(function(a,b){return(a.order||0)-(b.order||0)});if(!modules.length){el('taskEditor').innerHTML='<p class="module-empty-hint">暂无模块，点击新增模块开始拆分。</p>'}else{el('taskEditor').innerHTML=modules.map(function(m){var modTasks=state.draft.tasks.filter(function(t){return t.module_id===m.id});return '<div class="module-edit-card" data-module-id="'+esc(m.id)+'"><div class="module-edit-head"><input type="checkbox" class="module-select"><span class="module-drag-handle" draggable="true" title="拖动排序">⋮⋮</span><span class="module-code">'+esc(m.id)+'</span><input class="module-name-input" value="'+esc(m.name)+'" placeholder="模块名称"><span class="module-count-chip">'+modTasks.length+' 项子任务</span><button class="btn-small add-task-to-module" data-module="'+esc(m.id)+'" type="button">＋ 添加任务</button><button class="remove-module icon-danger" type="button">×</button></div><textarea class="module-desc-input" rows="2" placeholder="模块目标与交付边界">'+esc(m.description||'')+'</textarea>'+(modTasks.length?'<div class="module-task-preview">'+modTasks.slice(0,5).map(function(t){return '<span class="module-task-chip">'+esc(t.name)+' ('+t.estimated_hours+'h)</span>'}).join('')+(modTasks.length>5?'<span class="module-task-chip">+'+(modTasks.length-5)+' 项</span>':'')+'</div>':'')+'</div>'}).join('')}updateDraftFooter();var totalHours=state.draft.tasks.reduce(function(s,t){return s+t.estimated_hours},0);el('draftTotal').textContent=modules.length+' 个大模块 · '+state.draft.tasks.length+' 项子任务 · '+totalHours.toFixed(1)+'h';el('draftHint').textContent=modules.length<2?'建议至少拆出 2 个模块':'';el('addModuleBtn').onclick=function(){mutateDraft([{op:'add_module'}]).catch(function(e){showNotice(e.message,'error')})};el('mergeModuleBtn').onclick=mergeSelectedModules;if(el('redraftModuleBtn'))el('redraftModuleBtn').onclick=function(){generateDraft(true,el('redraftModuleBtn'))};document.querySelectorAll('.add-task-to-module').forEach(function(btn){btn.onclick=function(){mutateDraft([{op:'add',module_id:btn.dataset.module}]).catch(function(e){showNotice(e.message,'error')})}});bindModuleCards()}function bindModuleCards(){document.querySelectorAll('.module-edit-card').forEach(function(card){var removeBtn=card.querySelector('.remove-module');if(removeBtn){removeBtn.onclick=function(){var modTasks=state.draft.tasks.filter(function(t){return t.module_id===card.dataset.moduleId});if(modTasks.length){showNotice('请先在子任务拆解阶段移走该模块下的任务','info');return}if(!confirm('确定删除模块 '+card.dataset.moduleId+'？'))return;mutateDraft([{op:'remove_module',module_id:card.dataset.moduleId}]).catch(function(e){showNotice(e.message,'error')})}}var handle=card.querySelector('.module-drag-handle');if(handle){handle.ondragstart=function(e){card.classList.add('dragging');e.dataTransfer.effectAllowed='move';e.dataTransfer.setData('text/module-id',card.dataset.moduleId)};handle.ondragend=function(){card.classList.remove('dragging')};card.ondragover=function(e){e.preventDefault();e.dataTransfer.dropEffect='move'};card.ondrop=function(e){e.preventDefault();var src=e.dataTransfer.getData('text/module-id');if(!src||src===card.dataset.moduleId)return;var ids=(state.draft.modules||[]).slice().sort(function(a,b){return(a.order||0)-(b.order||0)}).map(function(m){return m.id});var from=ids.indexOf(src),to=ids.indexOf(card.dataset.moduleId);if(from<0||to<0||from===to)return;ids.splice(to,0,ids.splice(from,1)[0]);syncModules().then(function(){return mutateDraft([{op:'reorder_modules',ordered_module_ids:ids}])}).catch(function(e){showNotice(e.message,'error')})}}})}function mergeSelectedModules(){var ids=Array.from(document.querySelectorAll('.module-select:checked')).map(function(cb){return cb.closest('.module-edit-card').dataset.moduleId});if(ids.length<2){showNotice('请至少选中两个模块','info');return}mutateDraft([{op:'merge_modules',module_ids:ids}]).catch(function(e){showNotice(e.message,'error')})}
async function syncModules(){var ops=[];document.querySelectorAll('.module-edit-card').forEach(function(card){var moduleId=card.dataset.moduleId;var original=(state.draft.modules||[]).find(function(m){return m.id===moduleId});if(!original)return;var newName=card.querySelector('.module-name-input').value.trim();var newDesc=card.querySelector('.module-desc-input').value.trim();if(newName!==original.name||newDesc!==(original.description||'')){ops.push({op:'update_module',module_id:moduleId,module:Object.assign({},original,{name:newName,description:newDesc})})}});if(ops.length)state.draft=await jsonRequest('/api/draft/mutate',{plan:state.draft,operations:ops});return state.draft}
function renderLargeBackbones(){el('draftToolbar').innerHTML='<div class="toolbar-title"><h2>骨干认领</h2><p>添加骨干成员，再为每个模块指定负责人</p></div><div class="toolbar-actions"></div>';var modules=(state.draft.modules||[]).slice().sort(function(a,b){return(a.order||0)-(b.order||0)});var members=state.input.members||[];var memberNames=members.filter(function(m){return m.name}).map(function(m){return m.name});var claimed=modules.filter(function(m){return m.assignee_id}).length;el('draftSummary').innerHTML='<strong>'+memberNames.length+' 名骨干 · 已认领 '+claimed+' / '+modules.length+' 个模块</strong><p>先在下方添加骨干成员，再为每个模块选择负责人。骨干认领后，其下子任务默认归属该骨干。</p>';var panel='<div class="draft-member-panel"><div class="draft-member-head"><div><h3>骨干管理</h3><p>添加项目骨干，每个骨干可认领一个大模块</p></div><button class="text-btn" id="addBackboneBtn" type="button">＋ 添加骨干</button></div><div class="draft-member-list" id="backboneList">'+members.map(function(m,i){return '<div class="draft-member-row" data-idx="'+i+'"><input class="bb-name" value="'+esc(m.name||'')+'" placeholder="骨干姓名"><input class="bb-skills" value="'+esc((m.skill_tags||[]).join(','))+'" placeholder="技能标签，逗号分隔"><div class="hours-input"><input class="bb-hours" type="number" min=".5" step=".5" value="'+(m.daily_available_hours||4)+'"><span>h/天</span></div><button class="icon-danger remove-bb" type="button">×</button></div>'}).join('')+'</div></div>';var cards=modules.map(function(m){var taskCount=state.draft.tasks.filter(function(t){return t.module_id===m.id}).length;return '<div class="module-claim-card" data-module-id="'+esc(m.id)+'"><div class="module-claim-title"><span class="module-code">'+esc(m.id)+'</span><div><strong>'+esc(m.name)+'</strong>'+(m.description?'<span>'+esc(m.description)+'</span>':'')+'</div></div><div class="module-claim-meta">'+taskCount+' 项子任务</div><label>骨干<select class="module-owner-select" data-module-owner="'+esc(m.id)+'"><option value="">未认领</option>'+memberNames.map(function(name){return '<option '+(name===m.assignee_id?'selected':'')+'>'+esc(name)+'</option>'}).join('')+'</select></label></div>'}).join('');el('taskEditor').innerHTML=panel+cards;updateDraftFooter();el('draftTotal').textContent=memberNames.length+' 名骨干 · '+claimed+' / '+modules.length+' 已认领';el('draftHint').textContent=memberNames.length===0?'请先添加骨干成员':(claimed<modules.length?'尚有模块未认领':'');el('addBackboneBtn').onclick=function(){if(!state.input.members)state.input.members=[];state.input.members.push({name:'',skill_tags:[],daily_available_hours:4});renderLargeBackbones()};document.querySelectorAll('.remove-bb').forEach(function(btn){btn.onclick=function(){var row=btn.closest('.draft-member-row');var idx=+row.dataset.idx;var removedName=state.input.members[idx]?state.input.members[idx].name:'';state.input.members.splice(idx,1);if(removedName){(state.draft.modules||[]).forEach(function(m){if(m.assignee_id===removedName)m.assignee_id=null})}renderLargeBackbones()}});document.querySelectorAll('.bb-name').forEach(function(inp){inp.addEventListener('blur',function(){var names=[];document.querySelectorAll('.bb-name').forEach(function(n){var v=n.value.trim();if(v)names.push(v)});state.input.members.forEach(function(m,i){if(names[i]!==undefined)m.name=names[i]});state.input.members=state.input.members.filter(function(m){return m.name});document.querySelectorAll('[data-module-owner]').forEach(function(sel){var current=sel.value;var html='<option value="">未认领</option>';names.forEach(function(n){html+='<option value="'+esc(n)+'" '+(n===current?'selected':'')+'>'+esc(n)+'</option>'});sel.innerHTML=html})})});document.querySelectorAll('[data-module-owner]').forEach(function(sel){sel.onchange=function(){var moduleId=sel.dataset.moduleOwner;var module=(state.draft.modules||[]).find(function(m){return m.id===moduleId});if(module)module.assignee_id=sel.value||null;renderLargeBackbones()}})}async function syncBackbones(){if(document.querySelector('#backboneList')){var collected=[];document.querySelectorAll('.draft-member-row').forEach(function(row){var name=row.querySelector('.bb-name')?row.querySelector('.bb-name').value.trim():'';if(!name)return;var skills=row.querySelector('.bb-skills')?splitTags(row.querySelector('.bb-skills').value):[];var hours=row.querySelector('.bb-hours')?+row.querySelector('.bb-hours').value||4:4;collected.push({name:name,skill_tags:skills,daily_available_hours:hours,available_hours:hours*14,profile_mode:'tags',bio:''})});state.input.members=collected}var ops=[];document.querySelectorAll('[data-module-owner]').forEach(function(sel){var moduleId=sel.dataset.moduleOwner;var original=(state.draft.modules||[]).find(function(m){return m.id===moduleId});if(!original)return;if((original.assignee_id||'')!==sel.value){ops.push({op:'update_module',module_id:moduleId,module:Object.assign({},original,{assignee_id:sel.value||null})})}});if(ops.length)state.draft=await jsonRequest('/api/draft/mutate',{plan:state.draft,operations:ops});return state.draft}function renderLargeTasks(){el('draftToolbar').innerHTML='<div class="toolbar-title"><h2>子任务拆解</h2><p>编辑各模块下的子任务</p></div><div class="toolbar-actions"><button class="btn btn-ghost" id="addTaskBtn">＋ 新增任务</button><button class="btn btn-ghost" id="mergeTaskBtn">合并选中</button></div>';el('draftSummary').innerHTML='<strong>'+esc(state.draft.summary)+'</strong><p>编辑各模块下的子任务。</p>';var modules=(state.draft.modules||[]).slice().sort(function(a,b){return(a.order||0)-(b.order||0)});el('taskEditor').innerHTML=modules.map(function(m){var tasks=state.draft.tasks.filter(function(t){return t.module_id===m.id}).sort(function(a,b){return(a.order||0)-(b.order||0)});return '<div class="module-edit-card"><div class="module-edit-head"><span class="module-code">'+esc(m.id)+'</span><strong style="font-size:14px">'+esc(m.name)+'</strong><span class="module-count-chip">'+tasks.length+' 项</span><button class="btn-small add-task-to-module" data-module="'+esc(m.id)+'">＋ 添加子任务</button></div><div class="module-task-list">'+tasks.map(renderTaskCard).join('')+'</div></div>'}).join('');updateDraftFooter();var total=state.draft.tasks.reduce(function(s,t){return s+t.estimated_hours},0);el('draftTotal').textContent=state.draft.tasks.length+' 项子任务 · '+total.toFixed(1)+'h';el('addTaskBtn').onclick=function(){var firstMod=(state.draft.modules||[])[0];mutateDraft([{op:'add',module_id:firstMod?firstMod.id:''}]).catch(function(e){showNotice(e.message,'error')})};el('mergeTaskBtn').onclick=mergeSelectedTasks;document.querySelectorAll('.add-task-to-module').forEach(function(btn){btn.onclick=function(){mutateDraft([{op:'add',module_id:btn.dataset.module}]).catch(function(e){showNotice(e.message,'error')})}});bindTaskCards()}
async function syncCurrentStage(){if(!isLargeProject())return syncDraftTasks();if(state.largeStage==='modules')return syncModules();if(state.largeStage==='backbones')return syncBackbones();return syncDraftTasks()}
async function onConfirmDraft(){var btn=el('confirmDraftBtn');var oldText=btn.textContent;btn.disabled=true;btn.innerHTML='<span class="spinner-inline"></span>处理中…';try{if(isLargeProject()&&state.largeStage==='modules'){await syncModules();state.largeStage='backbones';renderDraftView();state.activeStep=2;renderSteps()}else if(isLargeProject()&&state.largeStage==='backbones'){await syncBackbones();state.largeStage='tasks';renderDraftView();state.activeStep=3;renderSteps()}else{await syncDraftTasks();var data=await jsonRequest('/api/confirm-draft',{input:state.input,plan:state.draft});state.plan=data;state.automatic=JSON.parse(JSON.stringify(data));['saveBtn','exportMdBtn','exportDocxBtn','exportPdfBtn'].forEach(function(b){el(b).disabled=false});renderBoard();setView('board',isLargeProject()?4:2);rebuildBaselineKeepHistory();showNotice('自动分工已完成，可拖拽调整','success')}}catch(error){showNotice(error.message,'error')}finally{btn.disabled=false;btn.textContent=oldText}}
﻿﻿function renderBoardToolbar(){var toolbar=el('boardToolbar');if(isLargeProject()){el('largeBoardTabs').classList.remove('hidden');el('largeBoardTabs').innerHTML='<button class="large-board-tab '+(state.largeBoardTab==='modules'?'active':'')+'" data-board-tab="modules">模块分工</button><button class="large-board-tab '+(state.largeBoardTab==='volunteers'?'active':'')+'" data-board-tab="volunteers">志愿者招募</button>';el('largeBoardTabs').querySelectorAll('.large-board-tab').forEach(function(btn){btn.onclick=function(){state.largeBoardTab=btn.dataset.boardTab;renderBoard()}});toolbar.innerHTML='<div class="toolbar-title"><h2>'+(state.largeBoardTab==='modules'?'模块分工':'志愿者招募')+'</h2></div>'}else{el('largeBoardTabs').classList.add('hidden');toolbar.innerHTML='<div class="toolbar-title"><h2>智能分工</h2><p>拖拽任务卡或下拉选择负责人</p></div><div class="toolbar-actions"><button class="btn btn-ghost" id="resetAssignBtn">恢复自动分工</button></div>';if(el('resetAssignBtn'))el('resetAssignBtn').onclick=resetAssignment}}
function renderBoard(){renderBoardToolbar();if(isLargeProject()&&state.largeBoardTab==='volunteers'){el('workloadSummary').innerHTML='';el('balanceWarnings').innerHTML='';renderVolunteerRecruit();return}var names=state.plan.input.members.map(function(m){return m.name});if(isLargeProject())renderLargeBoard(names);else renderSmallBoard(names);refreshWorkload().catch(function(e){showNotice(e.message,'error')})}
function renderSmallBoard(names){var groups={},assistGroups={};names.concat(['未分配']).forEach(function(n){groups[n]=[];assistGroups[n]=[]});state.plan.plan.tasks.forEach(function(task){var owner=task.assignee_id||'未分配';if(groups[owner])groups[owner].push(task);var qa=(state.plan.qa_matrix&&state.plan.qa_matrix.assignments||[]).find(function(a){return a.task_id===task.id});var collabs=[];if(qa){if(qa.qa_primary&&qa.qa_primary!==owner)collabs.push(qa.qa_primary);(qa.qa_support||[]).forEach(function(s){if(s&&s!==owner&&collabs.indexOf(s)<0)collabs.push(s)})}else{(task.collaborator_ids||[]).forEach(function(c){if(c!==owner)collabs.push(c)})}if(qa){if(qa.qa_primary&&qa.qa_primary!==owner&&assistGroups[qa.qa_primary])assistGroups[qa.qa_primary].push({task:task,type:'primary'});(qa.qa_support||[]).forEach(function(s){if(s&&s!==owner&&assistGroups[s])assistGroups[s].push({task:task,type:'support'})})}else{collabs.forEach(function(cn){if(assistGroups[cn])assistGroups[cn].push({task:task,type:'support'})})}});el('board').className='assignment-board';el('board').innerHTML=Object.keys(groups).map(function(owner){var hours=groups[owner].reduce(function(s,t){return s+t.estimated_hours},0);var assistH=assistGroups[owner].reduce(function(s,item){return s+item.task.estimated_hours*(item.type==='primary'?0.3:0.15)},0);var meta=groups[owner].length+' 项'+(assistGroups[owner].length?' · 协助'+assistGroups[owner].length:'')+' · '+(hours+assistH).toFixed(1)+'h';return '<section class="member-column" data-owner="'+esc(owner)+'"><header><div class="avatar">'+esc(owner.slice(0,1))+'</div><div><strong>'+esc(owner)+'</strong><span>'+meta+'</span></div></header><div class="member-task-list">'+groups[owner].map(function(task){return renderAssignmentCard(task,names)}).join('')+assistGroups[owner].map(function(item){return '<article class="assignment-card assist-card"><div class="assignment-title"><strong>'+esc(item.task.name)+'</strong><span>'+(item.type==='primary'?'主要协助':'协助')+'</span></div><div class="assignment-meta">'+esc(item.task.execution_stage)+'</div></article>'}).join('')+'</div></section>'}).join('');bindBoard(names)}
function renderAssignmentCard(task,names){return '<article class="assignment-card" draggable="true" data-task="'+esc(task.id)+'"><div class="assignment-title"><strong>'+esc(task.name)+'</strong><span>'+task.estimated_hours+'h</span></div><div class="assignment-meta">'+esc(task.execution_stage)+' · '+esc((task.required_skills||[]).join(' / ')||'通用')+'</div><label>负责人<select class="owner-select"><option value="">未分配</option>'+names.map(function(n){return '<option value="'+esc(n)+'" '+(n===task.assignee_id?'selected':'')+'>'+esc(n)+'</option>'}).join('')+'</select></label><button type="button" class="collaborator-btn">协作者：'+esc((task.collaborator_ids||[]).join('、')||'无')+'</button></article>'}
function bindBoard(names){document.querySelectorAll('.assignment-card:not(.assist-card)').forEach(function(card){card.ondragstart=function(e){e.dataTransfer.effectAllowed='move';e.dataTransfer.setData('text/task-id',card.dataset.task)};var ownerSel=card.querySelector('.owner-select');if(ownerSel){ownerSel.onchange=function(){var task=state.plan.plan.tasks.find(function(t){return t.id===card.dataset.task});var old=task.assignee_id||'未分配';task.assignee_id=this.value||null;task.collaborator_ids=(task.collaborator_ids||[]).filter(function(n){return n!==task.assignee_id});recordDelta('任务 '+task.id+' 负责人：'+old+'→'+(task.assignee_id||'未分配'));renderBoard()}}var collabBtn=card.querySelector('.collaborator-btn');if(collabBtn){collabBtn.onclick=function(){var task=state.plan.plan.tasks.find(function(t){return t.id===card.dataset.task});var value=prompt('输入协作者姓名，用逗号分隔：',(task.collaborator_ids||[]).join(','));if(value===null)return;task.collaborator_ids=splitTags(value).filter(function(n){return names.indexOf(n)>=0&&n!==task.assignee_id});recordDelta('任务 '+task.id+' 协作者：'+(task.collaborator_ids.join(',')||'无'));renderBoard()}}});document.querySelectorAll('.member-column').forEach(function(column){column.ondragover=function(e){e.preventDefault();e.dataTransfer.dropEffect='move';column.classList.add('drag-over')};column.ondragleave=function(){column.classList.remove('drag-over')};column.ondrop=function(e){e.preventDefault();column.classList.remove('drag-over');var task=state.plan.plan.tasks.find(function(t){return t.id===e.dataTransfer.getData('text/task-id')});if(!task)return;var old=task.assignee_id||'未分配';task.assignee_id=column.dataset.owner==='未分配'?null:column.dataset.owner;task.collaborator_ids=(task.collaborator_ids||[]).filter(function(n){return n!==task.assignee_id});recordDelta('任务 '+task.id+' 负责人：'+old+'→'+(task.assignee_id||'未分配'));renderBoard()}})}
function renderLargeBoard(names){var modules=(state.plan.plan.modules||[]).slice().sort(function(a,b){return(a.order||0)-(b.order||0)});el('board').className='assignment-board board-large';el('board').innerHTML=modules.map(function(m){var tasks=state.plan.plan.tasks.filter(function(t){return t.module_id===m.id});return '<div class="board-module" data-module-id="'+esc(m.id)+'"><div class="board-module-head"><div class="board-module-title"><span class="module-code">'+esc(m.id)+'</span><div><strong>'+esc(m.name)+'</strong><span>'+tasks.length+' 项子任务</span></div></div><label>骨干<select class="module-owner-select" data-module-owner="'+esc(m.id)+'"><option value="">未认领</option>'+names.map(function(n){return '<option '+(n===m.assignee_id?'selected':'')+'>'+esc(n)+'</option>'}).join('')+'</select></label></div><div class="board-module-tasks">'+tasks.map(function(task){return renderAssignmentCard(task,names)}).join('')+'</div></div>'}).join('');document.querySelectorAll('[data-module-owner]').forEach(function(sel){sel.onchange=function(){var moduleId=sel.dataset.moduleOwner;var original=(state.plan.plan.modules||[]).find(function(m){return m.id===moduleId});if(original)original.assignee_id=sel.value||null}});bindBoard(names)}
function resetAssignment(){if(!state.automatic)return;state.plan=JSON.parse(JSON.stringify(state.automatic));renderBoard();showNotice('已恢复自动分工','info')}
async function refreshWorkload(){var snapshot=await jsonRequest('/api/workload',state.plan);var members=snapshot.members;el('workloadSummary').innerHTML=Object.keys(members).map(function(name){var item=members[name];var cnt=item.task_count+(item.assist_count?' +协助'+item.assist_count:'');return '<div class="workload-card"><div><strong>'+esc(name)+'</strong><span>'+cnt+' · '+item.total_hours+'h</span></div><div class="load-track"><i style="width:'+Math.min(100,item.share*100)+'%"></i></div><small>'+Math.round(item.share*100)+'% 团队工作量</small></div>'}).join('');el('balanceWarnings').innerHTML=snapshot.warnings.length?'<div class="warning-box"><strong>分工建议</strong><span>'+snapshot.warnings.map(esc).join('；')+'</span></div>':'<div class="success-box">当前技能匹配和工作量较为均衡</div>'}
﻿﻿function renderVolunteerRecruit(){var modules=(state.plan.plan.modules||[]).slice().sort(function(a,b){return(a.order||0)-(b.order||0)});var recruitTasks=state.plan.plan.tasks.filter(function(t){return(t.extra_helpers_needed||0)>0});el('board').className='assignment-board board-large';if(!recruitTasks.length){el('board').innerHTML='<div class="success-box">当前没有需要招募志愿者的任务。</div>';return}var byModule={};recruitTasks.forEach(function(t){var mid=t.module_id||'_none';if(!byModule[mid])byModule[mid]=[];byModule[mid].push(t)});el('board').innerHTML='<div class="volunteer-recruit"><div class="volunteer-recruit-head"><h3>志愿者招募</h3><p>为需要额外人手的任务招募外部志愿者。</p></div>'+modules.filter(function(m){return byModule[m.id]}).map(function(m){return '<div class="volunteer-module-section" data-module-id="'+esc(m.id)+'"><header><strong>'+esc(m.name)+'</strong><span>需招募 '+byModule[m.id].length+' 项</span></header>'+byModule[m.id].map(function(task){return renderVolunteerTask(task)}).join('')+'</div>'}).join('')+'</div>';bindVolunteerControls()}
function renderVolunteerTask(task){var pool=state.plan.volunteer_pool||[];var taskVols=pool.filter(function(v){return v.task_id===task.id});var need=task.extra_helpers_needed||0;var active=taskVols.filter(function(v){return v.status!=='已婉拒'}).length;var full=active>=need;var rows=taskVols.map(function(v,idx){return '<div class="volunteer-row" data-volunteer-idx="'+idx+'" data-task-id="'+esc(task.id)+'"><input class="volunteer-name" value="'+esc(v.name)+'" placeholder="姓名"><input class="volunteer-contact" value="'+esc(v.contact||'')+'" placeholder="联系方式"><select class="volunteer-status">'+['待确认','已确认','已婉拒'].map(function(s){return '<option '+(s===v.status?'selected':'')+'>'+s+'</option>'}).join('')+'</select><input class="volunteer-note" value="'+esc(v.note||'')+'" placeholder="备注"><button class="volunteer-remove" type="button">×</button></div>'}).join('');return '<div class="volunteer-task" data-task-id="'+esc(task.id)+'"><header><strong>'+esc(task.name)+'</strong><span>需 '+need+' 人 · 已认领 '+active+'</span></header><div class="volunteer-list">'+(rows||'<div class="volunteer-empty">暂无认领</div>')+'</div>'+(full?'<div class="volunteer-full">已满员（'+active+'/'+need+'）</div>':'<div class="volunteer-add"><input class="volunteer-add-name" placeholder="志愿者姓名"><input class="volunteer-add-contact" placeholder="联系方式（可选）"><button class="volunteer-add-btn" type="button" data-task-id="'+esc(task.id)+'">＋ 添加</button></div>')+'</div>'}
function bindVolunteerControls(){document.querySelectorAll('.volunteer-remove').forEach(function(btn){btn.onclick=function(){var row=btn.closest('.volunteer-row');var taskId=row.dataset.taskId,idx=+row.dataset.volunteerIdx;var pool=state.plan.volunteer_pool||[];var taskPool=pool.filter(function(v){return v.task_id===taskId});if(taskPool[idx]){pool.splice(pool.indexOf(taskPool[idx]),1);saveVolunteers()}}});document.querySelectorAll('.volunteer-add-btn').forEach(function(btn){btn.onclick=function(){var taskId=btn.dataset.taskId;var section=btn.closest('.volunteer-task');var name=section.querySelector('.volunteer-add-name').value.trim();var contact=section.querySelector('.volunteer-add-contact').value.trim();if(!name){showNotice('请填写志愿者姓名','info');return}if(!state.plan.volunteer_pool)state.plan.volunteer_pool=[];state.plan.volunteer_pool.push({name:name,task_id:taskId,status:'待确认',contact:contact,note:''});saveVolunteers()}});document.querySelectorAll('.volunteer-row input, .volunteer-row select').forEach(function(field){field.onchange=saveVolunteers})}
async function saveVolunteers(){var pool=[];document.querySelectorAll('.volunteer-task').forEach(function(taskSection){var taskId=taskSection.dataset.taskId;taskSection.querySelectorAll('.volunteer-row').forEach(function(row){pool.push({name:row.querySelector('.volunteer-name').value.trim(),task_id:taskId,status:row.querySelector('.volunteer-status').value,contact:row.querySelector('.volunteer-contact').value.trim(),note:row.querySelector('.volunteer-note').value.trim()})})});try{state.plan=await jsonRequest('/api/volunteers',{plan:state.plan,volunteers:pool});renderVolunteerRecruit()}catch(e){showNotice(e.message,'error')}}
async function onConfirmAssignment(){var btn=el('confirmAssignmentBtn');var oldText=btn.textContent;btn.disabled=true;btn.innerHTML='<span class="spinner-inline"></span>保存中…';try{var assignees={},collaborators={},moduleAssignees={};state.plan.plan.tasks.forEach(function(task){assignees[task.id]=task.assignee_id||'';collaborators[task.id]=task.collaborator_ids||[]});if(isLargeProject()){document.querySelectorAll('[data-module-owner]').forEach(function(sel){moduleAssignees[sel.dataset.moduleOwner]=sel.value})}state.plan=await jsonRequest('/api/manual-assignment',{plan:state.plan,assignees:assignees,collaborators:collaborators,module_assignees:moduleAssignees});renderFinal();setView('final',isLargeProject()?5:3);rebuildBaselineKeepHistory();showNotice('最终分工已确认','success')}catch(error){showNotice(error.message,'error')}finally{btn.disabled=false;btn.textContent=oldText}}
﻿﻿function renderFinal(){renderResultTab(state.resultTab)}
function statusOptions(current){return[['pending','待开始'],['in_progress','进行中'],['completed','已完成'],['blocked','阻塞']].map(function(item){return '<option value="'+item[0]+'" '+(item[0]===current?'selected':'')+'>'+item[1]+'</option>'}).join('')}
function renderGantt(){var tasks=state.plan.timeline.tasks||[];if(!tasks.length)return '<div class="success-box">暂无时间线数据</div>';var dates=tasks.flatMap(function(t){return[new Date(t.start_date),new Date(t.end_date)]});var min=new Date(Math.min.apply(null,dates)),max=new Date(Math.max.apply(null,dates));var span=Math.max(1,(max-min)/86400000+1);var legend='<div class="gantt-legend"><span><i class="legend-critical"></i>关键路径</span><span><i class="legend-urgent"></i>紧急</span><span><i class="legend-normal"></i>浮动充足</span><span><i class="legend-blocked"></i>阻塞</span></div>';var rows=tasks.map(function(task){var start=(new Date(task.start_date)-min)/86400000;var width=Math.max(1,(new Date(task.end_date)-new Date(task.start_date))/86400000+1);var left=start/span*100,w=width/span*100;var cls=task.status==='blocked'?'blocked':task.is_critical?'critical':(task.float_days!==undefined&&task.float_days<=1?'urgent':'normal');var floatLabel=task.is_critical?'关键':(task.float_days!==undefined?'浮动'+task.float_days+'d':'');var rowCls=task.status==='completed'?'is-completed':(task.status==='blocked'?'is-blocked':'');return '<div class="gantt-row '+rowCls+'"><span>'+esc(task.name)+'</span><div class="gantt-track"><i class="'+cls+'" style="left:'+left+'%;width:'+Math.max(2,w)+'%"></i></div><small>'+esc(String(task.start_date).slice(0,10))+' → '+esc(String(task.end_date).slice(0,10))+(floatLabel?' · '+floatLabel:'')+'</small></div>'}).join('');return '<div class="gantt-head"><strong>项目甘特图</strong><span>总工期 '+state.plan.timeline.total_days+' 工作日</span></div>'+legend+'<div class="gantt-chart">'+rows+'</div>'}
function renderResultTab(tab){state.resultTab=tab;document.querySelectorAll('#resultTabs button').forEach(function(button){button.classList.toggle('active',button.dataset.tab===tab)});var tasks=state.plan.plan.tasks;var completed=tasks.filter(function(t){return t.status==='completed'}).length;var total=tasks.length;var percent=Math.round(completed/Math.max(1,total)*100);var content='';if(tab==='tasks'){content='<div class="progress-card"><div><strong>项目进度</strong><span>'+completed+'/'+total+'（'+percent+'%）</span></div><div class="progress-track"><i style="width:'+percent+'%"></i></div></div>';if(isLargeProject()&&(state.plan.plan.modules||[]).length){var modules=state.plan.plan.modules.slice().sort(function(a,b){return(a.order||0)-(b.order||0)});content+=modules.map(function(m){var modTasks=tasks.filter(function(t){return t.module_id===m.id});return '<div class="final-module"><div class="final-module-head"><span class="module-code">'+esc(m.id)+'</span><div><strong>'+esc(m.name)+'</strong><span>骨干：'+esc(m.assignee_id||'未认领')+' · '+modTasks.length+' 项子任务</span></div></div><div class="final-grid">'+modTasks.map(renderFinalTaskCard).join('')+'</div></div>'}).join('')}else{content+='<div class="final-grid">'+tasks.map(renderFinalTaskCard).join('')+'</div>'}}if(tab==='timeline'){content=renderGantt()+'<div class="timeline-detail"><h3>排期明细</h3>'+(state.plan.timeline.tasks||[]).map(function(task){return '<div class="timeline-detail-row"><span class="'+(task.is_critical?'text-critical':'')+'">'+esc(task.name)+'</span><small>'+(task.is_critical?'关键路径':'浮动'+(task.float_days||0)+'d')+'</small><strong>'+esc(String(task.start_date).slice(0,10))+' → '+esc(String(task.end_date).slice(0,10))+'</strong></div>'}).join('')+'</div>'}if(tab==='matrix'){content='<table><thead><tr><th>任务</th><th>负责人</th><th>协作者</th><th>匹配度</th><th>状态</th></tr></thead><tbody>'+state.plan.qa_matrix.assignments.map(function(item){var task=state.plan.plan.tasks.find(function(t){return t.id===item.task_id});return '<tr><td>'+esc(item.task_name)+'</td><td>'+esc(item.presenter||'未分配')+'</td><td>'+esc([item.qa_primary].concat(item.qa_support||[]).filter(Boolean).join('、')||'无')+'</td><td>'+Math.round((item.score||0)*100)+'%</td><td>'+esc(task?task.status:'pending')+'</td></tr>'}).join('')+'</tbody></table>'}if(tab==='workload')content='<div id="workloadDetail" class="workload-detail"><p style="color:#6b7891">加载中…</p></div>';if(tab==='report'){var r=state.plan.report||{};content='<div class="report-box">';if(r.summary)content+='<h3>方案概要</h3><p>'+renderMd(r.summary)+'</p>';if(r.timeline_section)content+='<h3>时间线</h3><p>'+renderMd(r.timeline_section)+'</p>';if(r.qa_matrix_section)content+='<h3>分工矩阵</h3><p>'+renderMd(r.qa_matrix_section)+'</p>';if(r.risk_note)content+='<div class="risk-note">'+esc(r.risk_note)+'</div>';content+='</div>'}if(tab==='interview'){content='<div class="interview-panel"><div class="interview-head"><h3>评审预演</h3><p>AI 评委逐题提问并点评你的回答。</p></div><div class="interview-req"><label>评委关注点（可选）</label><textarea id="interviewRequirements" rows="3" placeholder="例如：重点围绕技术方案创新性展开"></textarea></div><div class="interview-actions"><button id="startInterviewBtn" class="btn btn-primary">开始模拟</button><button id="resetInterviewBtn" class="btn btn-ghost">重新开始</button></div><div id="interviewMessages" class="interview-messages"><div class="interview-placeholder">点击开始模拟后，AI 评委将逐题提问。</div></div><form id="interviewForm" class="interview-form hidden"><textarea id="interviewAnswer" rows="2" placeholder="输入回答…"></textarea><button type="submit">回答</button></form></div>'}if(tab==='members'){content='<div class="member-edit-panel"><div class="member-edit-head"><h3>成员管理</h3><p>调整成员或工时后自动重算分工与排期。</p></div><div id="memberEditList" class="member-edit-list"></div><div class="member-edit-actions"><button id="addMemberEditBtn" class="btn btn-ghost">＋ 添加成员</button><button id="applyMemberEditBtn" class="btn btn-primary">应用变更</button></div></div>'}el('resultContent').innerHTML=content;if(tab==='tasks')bindStatusControls();if(tab==='interview')bindInterviewControls();if(tab==='members')bindMemberEditControls();if(tab==='workload')renderWorkloadTab().catch(function(e){showNotice(e.message,'error')})}
function renderFinalTaskCard(task){return '<article class="final-card status-'+task.status+'"><div><span class="task-code">'+esc(task.id)+'</span><strong>'+esc(task.name)+'</strong></div><p>'+esc(task.description)+'</p><footer><span>'+esc(task.assignee_id||'未分配')+'</span><span>'+task.estimated_hours+'h</span><span>建议'+(task.suggested_people||1)+'人</span>'+(task.extra_helpers_needed?'<span class="volunteer-chip">需招'+task.extra_helpers_needed+'人</span>':'')+'<select class="status-select" data-task-status="'+esc(task.id)+'">'+statusOptions(task.status)+'</select></footer></article>'}
function bindStatusControls(){document.querySelectorAll('[data-task-status]').forEach(function(sel){sel.onchange=async function(){var taskId=sel.dataset.taskStatus;var task=state.plan.plan.tasks.find(function(t){return t.id===taskId});if(task)task.status=sel.value;try{state.plan=await jsonRequest('/api/recompute',state.plan);renderResultTab(state.resultTab);showNotice('状态已更新','success')}catch(e){showNotice(e.message,'error')}}})}
async function renderWorkloadTab(){var snapshot=await jsonRequest('/api/workload',state.plan);var target=el('workloadDetail');if(!target)return;target.innerHTML=Object.keys(snapshot.members).map(function(name){var item=snapshot.members[name];var cnt=item.task_count+(item.assist_count?' +协助'+item.assist_count:'');return '<article><div><strong>'+esc(name)+'</strong><span>'+cnt+' · '+item.total_hours+'h · '+Math.round(item.share*100)+'%</span></div><div class="load-track"><i style="width:'+Math.min(100,item.share*100)+'%"></i></div><p>'+Object.keys(item.stage_hours).map(function(stage){return esc(stage)+' '+item.stage_hours[stage]+'h'}).join(' · ')+'</p></article>'}).join('')}
﻿﻿function bindInterviewControls(){var startBtn=el('startInterviewBtn'),resetBtn=el('resetInterviewBtn');var form=el('interviewForm'),input=el('interviewAnswer');if(startBtn)startBtn.onclick=startInterviewChat;if(resetBtn)resetBtn.onclick=function(){resetInterviewChat();showNotice('已重新开始','info')};if(form)form.onsubmit=sendInterviewAnswer;if(input)input.disabled=!ivChat.started}
async function startInterviewChat(){var btn=el('startInterviewBtn');btn.disabled=true;btn.innerHTML='<span class="spinner-inline"></span>生成中…';try{var req=el('interviewRequirements');var data=await jsonRequest('/api/interview',{plan:state.plan.plan,qa_matrix:state.plan.qa_matrix,user_requirements:req?req.value.trim():''});ivChat.started=true;ivChat.messages=[];var firstQ=(data.questions&&data.questions[0])||'请介绍你们项目的核心思路。';ivChat.messages.push({role:'assistant',content:'模拟评审开始。我会逐题提问并点评。\n\n'+firstQ});renderInterviewChat();el('interviewForm').classList.remove('hidden');el('interviewAnswer').disabled=false}catch(e){showNotice(e.message,'error')}finally{btn.disabled=false;btn.textContent='开始模拟'}}
function resetInterviewChat(){ivChat.started=false;ivChat.messages=[];var msgBox=el('interviewMessages');if(msgBox)msgBox.innerHTML='<div class="interview-placeholder">点击开始模拟后，AI 评委将逐题提问。</div>';var form=el('interviewForm');if(form)form.classList.add('hidden')}
function renderInterviewChat(){var msgBox=el('interviewMessages');if(!msgBox)return;msgBox.innerHTML=ivChat.messages.map(function(msg){return '<div class="'+(msg.role==='user'?'user-msg':'assistant-msg')+'">'+esc(msg.content)+'</div>'}).join('');msgBox.scrollTop=msgBox.scrollHeight}
async function sendInterviewAnswer(e){e.preventDefault();var input=el('interviewAnswer');var ans=input.value.trim();var btn=el('interviewForm').querySelector('button');if(!ans||btn.disabled)return;ivChat.messages.push({role:'user',content:ans});input.value='';renderInterviewChat();btn.disabled=true;try{var req=el('interviewRequirements');var data=await jsonRequest('/api/interview/chat',{plan:state.plan.plan,qa_matrix:state.plan.qa_matrix,user_answer:ans,history:ivChat.messages.slice(0,-1),user_requirements:req?req.value.trim():''});ivChat.messages.push({role:'assistant',content:typeof data.reply==='string'?data.reply:String(data.reply||'')});renderInterviewChat()}catch(err){showNotice(err.message,'error')}finally{btn.disabled=false}}
function bindMemberEditControls(){var list=el('memberEditList');list.innerHTML='';state.plan.input.members.forEach(function(m){addMemberEditRow(m)});el('addMemberEditBtn').onclick=function(){addMemberEditRow({name:'',daily_available_hours:4,skill_tags:[]})};el('applyMemberEditBtn').onclick=applyMemberEdit}
function addMemberEditRow(member){var list=el('memberEditList');var row=document.createElement('div');row.className='member-edit-row';row.innerHTML='<input class="edit-member-name" value="'+esc(member.name||'')+'" placeholder="姓名"><input class="edit-member-skills" value="'+esc((member.skill_tags||[]).join(','))+'" placeholder="技能标签"><div class="hours-input"><input class="edit-member-hours" type="number" min=".5" step=".5" value="'+(member.daily_available_hours||4)+'"><span>h/天</span></div><input class="edit-member-unavailable" value="" placeholder="不可用日期"><button class="icon-danger remove-edit-member" type="button">×</button>';row.querySelector('.remove-edit-member').onclick=function(){row.remove()};list.appendChild(row)}
async function applyMemberEdit(){var btn=el('applyMemberEditBtn');btn.disabled=true;btn.innerHTML='<span class="spinner-inline"></span>计算中…';try{var existingNames=state.plan.input.members.map(function(m){return m.name});var removed=[],updated={},added=[],currentNames=[];document.querySelectorAll('.member-edit-row').forEach(function(row){var name=row.querySelector('.edit-member-name').value.trim();if(!name)return;currentNames.push(name);updated[name]=+row.querySelector('.edit-member-hours').value||4});removed=existingNames.filter(function(n){return currentNames.indexOf(n)<0});document.querySelectorAll('.member-edit-row').forEach(function(row){var name=row.querySelector('.edit-member-name').value.trim();if(name&&existingNames.indexOf(name)<0){added.push({name:name,daily_available_hours:+row.querySelector('.edit-member-hours').value||4,skill_tags:splitTags(row.querySelector('.edit-member-skills').value)})}});state.plan=await jsonRequest('/api/edit-members',{plan:state.plan,removed_members:removed,updated_members:updated,added_members:added});renderResultTab('members');showNotice('成员变更已应用，分工与排期已重算','success')}catch(e){showNotice(e.message,'error')}finally{btn.disabled=false;btn.textContent='应用变更'}}
function buildChatBaseline(){var lines=[];if(state.plan){var fp=state.plan,c=fp.input.course,large=fp.input.project_mode==='large_project';lines.push('项目：'+c.name);lines.push('背景：'+(c.description||'').slice(0,200));lines.push('截止：'+fp.input.deadline);lines.push((large?'骨干：':'团队：')+fp.input.members.map(function(m){return m.name+'(技能:'+(m.skill_tags||[]).join(',')+')'}).join(' '));if(large&&(fp.plan.modules||[]).length){lines.push('模块 '+fp.plan.modules.length+' 个');fp.plan.modules.forEach(function(m){var mt=fp.plan.tasks.filter(function(t){return t.module_id===m.id});lines.push('  '+m.id+' '+m.name+'(骨干:'+(m.assignee_id||'未认领')+','+mt.length+'子任务)')})}lines.push('任务 '+fp.plan.tasks.length+'项，总工时 '+fp.plan.tasks.reduce(function(s,t){return s+t.estimated_hours},0)+'h');fp.plan.tasks.forEach(function(t){lines.push('  '+t.id+' '+t.name+'('+t.estimated_hours+'h,'+(t.assignee_id||'未分配')+')')});if(fp.timeline&&fp.timeline.tasks&&fp.timeline.tasks.length)lines.push('工期 '+fp.timeline.total_days+'天');if(fp.report&&fp.report.risk_note)lines.push('风险：'+fp.report.risk_note.slice(0,150))}else if(state.draft){var ts=state.draft.tasks;lines.push('任务草案 '+ts.length+' 项');ts.forEach(function(t){lines.push('  '+t.id+' '+t.name+'('+t.estimated_hours+'h)')})}else{lines.push('尚未生成方案')}return lines.join('\n')}
function resetChatMemory(){state.chatBaseline=buildChatBaseline();state.chatHistory=[];state.chatDelta='';var msgBox=el('messages');if(msgBox)msgBox.innerHTML='<div class="assistant-msg">你好，我可以分析任务拆解、工时和分工，并给出调整建议。</div>'}
function recordDelta(d){if(!d)return;state.chatDelta=state.chatDelta?state.chatDelta+'；'+d:d}
function rebuildBaselineKeepHistory(){state.chatBaseline=buildChatBaseline();state.chatDelta=''}
function openAssistant(){el('assistantDrawer').classList.remove('hidden');positionAssistantDrawer();if(!state.chatBaseline)resetChatMemory()}
function closeAssistant(){el('assistantDrawer').classList.add('hidden')}
function positionAssistantDrawer(){var drawer=el('assistantDrawer'),btn=el('assistantBtn');var rect=btn.getBoundingClientRect();var dw=360,dh=510;var left=rect.right-dw;if(left<10)left=10;var top=rect.top-dh-10;if(top<70)top=rect.bottom+10;drawer.style.left=left+'px';drawer.style.top=top+'px';drawer.style.right='auto';drawer.style.bottom='auto'}
async function sendChat(e){e.preventDefault();var input=el('chatInput');var msg=input.value.trim();var btn=el('chatForm').querySelector('button');if(!msg||btn.disabled)return;input.value='';var msgBox=el('messages');msgBox.innerHTML+='<div class="user-msg">'+esc(msg)+'</div>';msgBox.scrollTop=msgBox.scrollHeight;btn.disabled=true;btn.innerHTML='<span class="spinner-inline"></span>';try{var data=await jsonRequest('/api/chat',{message:msg,plan:state.plan,draft:state.draft&&!state.plan?state.draft:null,input:state.input,history:state.chatHistory,delta:state.chatDelta});var reply=typeof data.reply==='string'?data.reply:String(data.reply||'');state.chatHistory.push({role:'user',content:msg});state.chatHistory.push({role:'assistant',content:reply});msgBox.innerHTML+='<div class="assistant-msg">'+esc(reply)+'</div>';msgBox.scrollTop=msgBox.scrollHeight}catch(err){msgBox.innerHTML+='<div class="assistant-msg muted">请求失败：'+esc(err.message)+'</div>'}finally{btn.disabled=false;btn.textContent='发送'}}
﻿﻿async function savePlan(){if(!state.plan)return;try{var d=await jsonRequest('/api/save',state.plan);state.lastSavedFilename=d.filename;showNotice('已保存：'+d.filename,'success')}catch(e){showNotice(e.message,'error')}}
async function showHistory(q){try{var url='/api/plans';if(q)url+='?q='+encodeURIComponent(q);var r=await fetch(url);if(!r.ok){showNotice('获取失败（HTTP '+r.status+'）','error');return}var d=await r.json();var plans=d.plans||[];if(!plans.length){el('planList').innerHTML='<p class="modal-empty">暂无历史方案</p>';el('modal').classList.remove('hidden');return}el('planList').innerHTML=plans.map(function(p){return '<div class="plan-item'+(p.filename===state.lastSavedFilename?' plan-item-new':'')+'"><button data-file="'+esc(p.filename)+'"><span>'+esc(p.filename)+'</span><small>'+(p.size/1024).toFixed(1)+' KB</small></button><button class="delete-plan icon-danger" data-delete="'+esc(p.filename)+'">×</button></div>'}).join('');el('modal').classList.remove('hidden');document.querySelectorAll('#planList [data-file]').forEach(function(b){b.onclick=function(){loadPlan(b.dataset.file)}});document.querySelectorAll('#planList [data-delete]').forEach(function(b){b.onclick=async function(){if(!confirm('确定删除 '+b.dataset.delete+'？'))return;try{await fetch('/api/plans/'+encodeURIComponent(b.dataset.delete),{method:'DELETE'});showNotice('已删除','success');if(state.lastSavedFilename===b.dataset.delete)state.lastSavedFilename=null;showHistory(el('planSearch').value)}catch(e){showNotice(e.message,'error')}}})}catch(e){showNotice('获取失败：'+e.message,'error')}}
async function loadPlan(fn){var r=await fetch('/api/load/'+encodeURIComponent(fn));var d=await r.json();if(!r.ok)return showNotice(d.detail||'载入失败','error');if(!d.report)d.report={summary:'',timeline_section:'',qa_matrix_section:'',risk_note:''};if(!d.timeline)d.timeline={tasks:[],critical_path:[],total_days:0,note:''};if(!d.qa_matrix)d.qa_matrix={assignments:[],workload:{},note:''};if(!d.plan)d.plan={tasks:[],modules:[]};if(!d.plan.modules)d.plan.modules=[];if(!d.volunteer_pool)d.volunteer_pool=[];state.plan=d;state.input=d.input;state.draft=d.plan;state.automatic=JSON.parse(JSON.stringify(d));if(d.input&&d.input.project_mode==='large_project'){state.largeStage='tasks';state.largeBoardTab='modules'}['saveBtn','exportMdBtn','exportDocxBtn','exportPdfBtn'].forEach(function(b){el(b).disabled=false});el('modal').classList.add('hidden');renderFinal();setView('final',isLargeProject()?5:3);resetChatMemory()}
async function exportPlan(fmt){if(!state.plan)return;try{var r=await fetch('/api/export/'+fmt,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(state.plan)});if(!r.ok){var e=await r.json();throw Error(e.detail||'导出失败')}var blob=await r.blob();var url=URL.createObjectURL(blob);var a=document.createElement('a');a.href=url;a.download='plan_report.'+(fmt==='markdown'?'md':fmt);a.click();URL.revokeObjectURL(url);showNotice('已导出 '+fmt.toUpperCase(),'success')}catch(e){showNotice(e.message,'error')}}
function bindAssistantDrag(){var btn=el('assistantBtn');var dragging=false,sx,sy,ol,ot;btn.addEventListener('mousedown',function(e){dragging=true;sx=e.clientX;sy=e.clientY;var rect=btn.getBoundingClientRect();ol=rect.left;ot=rect.top;btn.classList.add('dragging');e.preventDefault()});document.addEventListener('mousemove',function(e){if(!dragging)return;btn.style.left=(ol+e.clientX-sx)+'px';btn.style.top=(ot+e.clientY-sy)+'px';btn.style.right='auto';btn.style.bottom='auto'});document.addEventListener('mouseup',function(){if(dragging){dragging=false;btn.classList.remove('dragging')}});btn.addEventListener('touchstart',function(e){var t=e.touches[0];dragging=true;sx=t.clientX;sy=t.clientY;var rect=btn.getBoundingClientRect();ol=rect.left;ot=rect.top;btn.classList.add('dragging')});document.addEventListener('touchmove',function(e){if(!dragging)return;var t=e.touches[0];btn.style.left=(ol+t.clientX-sx)+'px';btn.style.top=(ot+t.clientY-sy)+'px';btn.style.right='auto';btn.style.bottom='auto';e.preventDefault()},{passive:false});document.addEventListener('touchend',function(){if(dragging){dragging=false;btn.classList.remove('dragging')}})}
function bindEvents(){el('projectForm').onsubmit=function(e){e.preventDefault();generateDraft(true)};el('addMemberBtn').onclick=function(){addMember()};el('demoCaseBtn').onclick=loadDemoCase;document.querySelectorAll('.mode-card').forEach(function(card){card.addEventListener('click',function(){document.querySelectorAll('.mode-card').forEach(function(c){c.classList.remove('active')});card.classList.add('active');card.querySelector('input[type="radio"]').checked=true;updateModeHint();renderSteps()})});el('chooseFileBtn').onclick=function(){el('files').click()};el('uploadBox').onclick=function(e){if(e.target.tagName!=='INPUT')el('files').click()};el('files').onchange=function(){state.files=Array.from(this.files);el('fileList').innerHTML=state.files.map(function(f){return '<span>'+esc(f.name)+'</span>'}).join('')};el('confirmDraftBtn').onclick=onConfirmDraft;el('confirmAssignmentBtn').onclick=onConfirmAssignment;el('resultTabs').addEventListener('click',function(e){if(e.target.dataset.tab)renderResultTab(e.target.dataset.tab)});el('backBoardBtn').onclick=function(){renderBoard();setView('board',isLargeProject()?4:2)};el('historyBtn').onclick=function(){showHistory('')};el('saveBtn').onclick=savePlan;el('exportMdBtn').onclick=function(){exportPlan('markdown')};el('exportDocxBtn').onclick=function(){exportPlan('docx')};el('exportPdfBtn').onclick=function(){exportPlan('pdf')};el('closeModal').onclick=function(){el('modal').classList.add('hidden')};el('planSearch').oninput=function(){showHistory(this.value)};el('assistantBtn').onclick=openAssistant;el('closeAssistant').onclick=closeAssistant;el('chatForm').onsubmit=sendChat;bindAssistantDrag()}
function init(){bindEvents();updateModeHint();renderSteps();addMember({name:'',skill_tags:[],daily_available_hours:4})}
document.addEventListener('DOMContentLoaded',init);
